**To Reproduce**
<!--
Steps to reproduce the behavior:
-->
Here are two test cases that can stably reproduce this panic
```
#[cfg(test)]
mod test {
    use std::sync::Arc;

    use arrow_array::{Int64Array, RecordBatch};
    use object_store::Error;
    use object_store::buffered::BufWriter;
    use object_store::local::LocalFileSystem;
    use object_store::path::Path;
    use object_store::{
        CopyOptions, GetOptions, GetResult, ListResult, MultipartUpload, ObjectMeta, ObjectStore,
        PutMultipartOptions, PutOptions, PutPayload, PutResult, Result,
    };
    use arrow_schema::{DataType, Field, Schema};
    use bytes::Bytes;
    use futures_util::stream::BoxStream;
    use parquet::{
        arrow::AsyncArrowWriter, basic::Compression, file::properties::WriterProperties,
    };
    use tokio::io::AsyncWriteExt;

    #[derive(Debug)]
    struct FailMultipartInitStore {
        inner: Arc<LocalFileSystem>,
    }

    impl FailMultipartInitStore {
        fn new(inner: Arc<LocalFileSystem>) -> Self {
            Self { inner }
        }
    }

    impl std::fmt::Display for FailMultipartInitStore {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "FailMultipartInitStore")
        }
    }

    #[async_trait::async_trait]
    impl ObjectStore for FailMultipartInitStore {
        async fn put_opts(
            &self,
            location: &Path,
            payload: PutPayload,
            opts: PutOptions,
        ) -> Result<PutResult> {
            self.inner.put_opts(location, payload, opts).await
        }

        async fn put_multipart_opts(
            &self,
            _location: &Path,
            _opts: PutMultipartOptions,
        ) -> Result<Box<dyn MultipartUpload>> {
            Err(Error::Generic {
                store: "FailMultipartInitStore",
                source: Box::new(std::io::Error::other("StorageFull")),
            })
        }

        async fn get_opts(&self, location: &Path, options: GetOptions) -> Result<GetResult> {
            self.inner.get_opts(location, options).await
        }

        fn delete_stream(
            &self,
            locations: BoxStream<'static, Result<Path>>,
        ) -> BoxStream<'static, Result<Path>> {
            self.inner.delete_stream(locations)
        }

        fn list(&self, prefix: Option<&Path>) -> BoxStream<'static, Result<ObjectMeta>> {
            self.inner.list(prefix)
        }

        async fn list_with_delimiter(&self, prefix: Option<&Path>) -> Result<ListResult> {
            self.inner.list_with_delimiter(prefix).await
        }

        async fn copy_opts(&self, from: &Path, to: &Path, options: CopyOptions) -> Result<()> {
            self.inner.copy_opts(from, to, options).await
        }
    }

    #[tokio::test]
    #[should_panic(expected = "`async fn` resumed after completion")]
    async fn test_buf_writer_shutdown_after_write_error_panics() {
        let dir = tempfile::tempdir().unwrap();
        let dir = dir.path().to_str().unwrap();
        let inner = Arc::new(LocalFileSystem::new_with_prefix(dir).unwrap());
        let store = Arc::new(FailMultipartInitStore::new(inner));
        let path = Path::from("panic-repro.parquet");
        let mut writer = BufWriter::with_capacity(store, path, 1);

        let err = writer
            .write_all_buf(&mut Bytes::from_static(b"trigger-prepare-error"))
            .await;
        assert!(
            err.is_err(),
            "expected write_all_buf to fail before shutdown"
        );

        let _ = writer.shutdown().await;
    }

    #[tokio::test]
    #[should_panic(expected = "`async fn` resumed after completion")]
    async fn test_async_arrow_writer_close_after_write_error_panics() {
        let dir = tempfile::tempdir().unwrap();
        let dir = dir.path().to_str().unwrap();
        let inner = Arc::new(LocalFileSystem::new_with_prefix(dir).unwrap());
        let store = Arc::new(FailMultipartInitStore::new(inner));
        let path = Path::from("panic-repro-arrow-writer.parquet");
        let buf_writer = BufWriter::with_capacity(store, path, 1);

        let schema = Arc::new(Schema::new(vec![Field::new(
            "value",
            DataType::Int64,
            false,
        )]));
        let writer_props = WriterProperties::builder()
            .set_compression(Compression::UNCOMPRESSED)
            .set_max_row_group_row_count(Some(1))
            .build();
        let mut writer =
            AsyncArrowWriter::try_new(buf_writer, schema.clone(), Some(writer_props)).unwrap();

        let values = Int64Array::from_iter_values([1_i64]);
        let batch = RecordBatch::try_new(schema, vec![Arc::new(values)]).unwrap();

        for _ in 0..100_000 {
            let _ = writer.write(&batch).await;
        }

        let _ = writer.close().await;
    }
}
```

**Expected behavior**
<!--
A clear and concise description of what you expected to happen.
-->
I believe that even when an error has already occurred, calling the shutdown or close method should return an error instead of triggering a panic.

**Additional context**
<!--
Add any other context about the problem here.
-->

**Describe the bug**
Rapidly creating the same file (as seen in the reproduction section) results in this error:
```
Generic LocalFileSystem error: Unable to open file test_dir\test\test.bin#2: Access is denied. (os error 5)
Generic LocalFileSystem error: Unable to open file test_dir\test\test.bin#1: Access is denied. (os error 5)
Generic LocalFileSystem error: Unable to open file test_dir\test\test.bin#3: Access is denied. (os error 5)
Generic LocalFileSystem error: Unable to open file test_dir\test\test.bin#5: Access is denied. (os error 5)
Generic LocalFileSystem error: Unable to open file test_dir\test\test.bin#2: Access is denied. (os error 5)
[...]
```

**To Reproduce**
```rust
use object_store::local::LocalFileSystem;
use object_store::path::Path;
use object_store::{Error, ObjectStore, PutMode, PutPayload};

#[tokio::main]
async fn main() {
    let store = LocalFileSystem::new_with_prefix("./test_dir").unwrap();
    for _ in 0..16 {
        let store = store.clone();
        tokio::spawn(async move {
            loop {
                match store
                    .put_opts(
                        &Path::parse("test/test.bin").unwrap(),
                        PutPayload::new(),
                        PutMode::Create.into(),
                    )
                    .await
                {
                    Ok(_) | Err(Error::AlreadyExists { .. }) => (),
                    Err(err) => println!("{err}"),
                }
            }
        });
    }

    tokio::time::sleep(std::time::Duration::from_secs_f32(1.5)).await;
}
```
with
```toml
[package]
name = "object-store-test"
version = "0.1.0"
edition = "2024"

[dependencies]
object_store = "0.13.2"
tokio = { version = "1.43.0", features = ["bytes", "default", "fs", "io-std", "io-util", "libc", "macros", "mio", "net", "rt", "rt-multi-thread", "socket2", "sync", "time", "tokio-macros"] }
```
and creating the `test_dir` directory, then `cargo run`.

The `tokio` features can likely be reduced by a lot, this is just what I copied from the `Cargo.toml` of the bigger project this occurred in, but I also doubt they are related to the error.

**Expected behavior**
The only expected error would've been `Error::AlreadyExists`, but it seemingly often fails before that when creating the staging file (so this is probably unrelated to the `PutMode` as well and would show up when trying to recreate the file rapidly, though that was not tested).

**Additional context**
I'm not sure if this may "really" be a bug in Rusts `std` or maybe even Windows & not `object_store`; based on a little digging I assume the error comes from `CreateFileW`, which does mention this:
> If you call CreateFile on a file that is pending deletion as a result of a previous call to [DeleteFile](https://learn.microsoft.com/en-us/windows/desktop/api/fileapi/nf-fileapi-deletefilea), the function fails. The operating system delays file deletion until all handles to the file are closed. [GetLastError](https://learn.microsoft.com/en-us/windows/desktop/api/errhandlingapi/nf-errhandlingapi-getlasterror) returns ERROR_ACCESS_DENIED.

I'm not sure if trying to rename a file (to the final path) actually counts as a deletion in Windows though, but at least on https://learn.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-createfilew I didn't find any more info that seems relevant to this exact issue, and I didn't search further than that either.

**Describe the bug**
<!--
A clear and concise description of what the bug is.
-->
When doing a multi-part upload with custom default headers, I got error
```
<Code>AccessDenied</Code><Message>There were headers present in the request which were not signed</Message><HeadersNotSigned>x-amz-source-arn, x-amz-source-account</HeadersNotSigned>
```

**To Reproduce**
<!--
Steps to reproduce the behavior:
-->
```
use object_store::ClientOptions;
use object_store::HeaderMap;
use object_store::ObjectStoreExt;
use object_store::aws::AmazonS3Builder;
use object_store::path::Path;

#[tokio::main]
async fn main() {
    let mut headers = HeaderMap::new();
    headers.insert("x-amz-source-account", "123456789111".parse().unwrap());
    headers.insert(
        "x-amz-source-arn",
        "arn:aws:s3:::source-bucket"
            .parse()
            .unwrap(),
    );

    let client = AmazonS3Builder::from_env()
        .with_bucket_name("bucket-name")
        .with_region("us-east-1")
        .with_client_options(ClientOptions::new().with_default_headers(headers))
        .build()
        .unwrap();

    let mut upload = client.put_multipart(&Path::from("test-mpu")).await.unwrap();
    let res = upload.complete().await.unwrap();
    println!("Upload complete: {:?}", res);
}

```

**Expected behavior**
<!--
A clear and concise description of what you expected to happen.
-->
Headers are signed. No error.

